    "question": "病人因水腫氣喘至急診求助，經檢傷分類後至內科急診區域等候。護理師幫該病人抽血後，等候 50 分鐘才取得抽血報告。家屬因不耐久候、情緒失控，大吵大鬧。約 10 分鐘後醫師來看病人並解說病 情。家屬抱怨等了 2 個小時，非常生氣，不聽醫療人員的說明。醫師見狀「冷處理」，家屬情緒更加 激動。根據上述情境，醫師為了等待抽血結果才能進行後續醫療處置，但病人家屬是希望醫師趕快緩 解病人氣喘及水腫的問題。依據 Daft & Marcic（2001）之分類，此為下列何種原因所產生的衝突？",
