    "question": "有關自殺防治通報關懷，以下敘述何者正確？ ①本市轄區各醫療機構對自殺未遂者應提供關懷服務，並應於發現後48 小 時內至衛生福利部公共衛生資訊入口網之自殺防治通報系統完成行政通 報。 ②關懷訪視員在接獲個案通報的三天內要進行初次關懷電訪，在進行電話 訪談時，若電話號碼錯誤或電話連續三天聯繫皆無人接聽，請再次與原 始通報單位確認個案電話及地址，以能聯繫到個案為原則。 ③若個案為再次自殺且此次自殺方式為上吊、燒炭、汽車廢氣、開瓦斯、 跳樓或喝農藥者等高風險自殺方式，須於接獲通報24 小時內進行初次關 懷。 ④原則上每位個案關懷訪視服務為 2 個月，每月至少 2 次，得依個案狀況 延長至6 個月，如必要再延長者，應經衛生局同意，始得延長。",
