    "question": "目前職棒傳出本季球賽可能受到黑道介入，扯出簽賭疑雲，柯南特別被邀請 至台灣協助警方偵辦此案，為釐清甲球隊 及其投手是否涉案，柯南決定運用 流行病學的相對勝算比（odds ratio）觀念來偵辦此案；柯南調出甲球隊過 去出賽紀錄，整理後發現在上一季甲球隊戰績為 18 勝 32 敗，本季目前戰績 為 10 勝 20 敗；又甲球隊中共有二位投手，波樂及愛卡，為了釐清 2 名投手 涉案的情形，柯南把甲球隊二季的戰績再作整理，發現波樂上季戰績為15 勝 5 敗，本季戰績為5 勝 5 敗，請問下列敘述何者為真？ a.上一季勝算為18/32 b.本季勝算為10/30 c.本季相對上一季之勝算比為 50/18 30/10 d.本季相對上一季之勝算比為 32/18 20/10 e.波樂本季相對上季勝算比為 f.愛卡的戰績本季相對上季的勝算比為3 g.波樂涉案可能極大，而愛卡涉案可能性相當低 h.波樂及愛卡的涉案可能均相當大",
