    "question": "根據某針對糖尿病前期進行介入之隨機試驗結果如下表： 組別 5 年糖尿病累積發生率 一般衛教（對照組） 0.50 飲食控制 0.35 運動 0.30 飲食+運動 0.25 藥物 0.45 請問下列敘述何者為真？ a.飲食控制介入比一般衛教之相對危險性為0.70 b.運動介入比一般衛教相差危險性為0.60 c.飲食加上運動介入對降低糖尿病危險的效益最好 d.若在「行動醫院、全民健檢」活動中發現1000 名糖尿病前期個案，若給予 一般衛教，五年後約會有500 名個案轉變為糖尿病個案 e.若對前述1000 名糖尿病前期個案進行運動介入 ， 預計五年後相較一般衛教 可減少200 名糖尿病個案",
