    "id": "tainan-94-0731-34",
    "question": "五十七歲的阿好嬸參加行動醫院後，接到衛生所通知說她糞便中有潛血反應， 建議她去接受大腸鏡檢查 。 阿好嬸心想 ， 明天早上跳土風舞時跟姐妹淘們討論 看看在做打算 。 隔天阿好嬸把健康檢查結果告訴土風舞的同夥後 ， 引來一陣嘲 諷 ， 包括 「衛生所做的檢查你也信」 、 「你可能是吃豬血 ， 大便才有血……」 、 「不 用看醫生啦！去代天府祭一祭就好了！」 等。聽完之後，阿好嬸心想大家這樣 說，如果去看醫生，ㄧ定會被笑。於是阿好嬸決定不接受衛生所的轉介安排， 聽信姐妹淘的建議 ， 先去王爺公那拿點爐丹回來吃 ， 改天再去南鯤鯓祭改一番 。 請問上述小故事，可利用那ㄧ個行為科學理論加以解釋？",
