    "id": "tainan-94-0731-40",
    "question": "某縣市發現鴨蛋戴奧辛含量過高，衛生人員欲了解是否食用含量過高之鴨蛋 和肝癌發生有關，進行有關下列流行病學調查。 a.依生產鴨蛋鴨農所在之地理區域分區進行是否距污染源愈近，肝癌發生率 愈高，此調查僅有問題是污染源之居民並未一定食用污染之鴨蛋。 b.調查食用污染源鴨蛋之民眾其肝癌發生狀況如何？ c.利用病例對照研究法，檢視飲用污染源鴨蛋和未食用者其肝癌發生率之差 異。 d.設計此種研究最大困難在於食用鴨蛋族群之界定。 上述何者為不正確？",
