    "id": "tainan-94-0731-41",
    "question": "某調查發現「多喝豆漿婦女，其乳癌發生率較少喝豆漿者低」推論喝豆漿可 以預防乳癌發生。 a.可能是喝豆漿婦女是屬於早起運動者，是運動防止乳癌發生而非喝豆漿， 因此可以觀察乳癌個案有早起運動百分比可以得到答案。 b.可能是年齡較輕者較年老者比較可能喝豆漿，而年齡和乳癌發生有關，因 此只要將研究對象限制在年輕樣本可以得到答案。 c.多喝豆漿婦女較多是傳統婦女 ， 屬於非上班族 ， 因此首胎生小孩年齡較早， 因此應觀察首胎生產年齡較早者是否喝豆漿比例較高，即可得到答案。 d.若不考慮倫理問題，設計研究來證明此推論最重要關鍵是有否收集上述可 能影響之第三因子。 上述何者為不正確？",
