    "question": "若欲證實「母親在駕駛時將小孩安全座椅放在駕駛座正後方 (L)或右後方(R) 小孩哭鬧頻率會不同」調查者徵求一群母親駕駛及小孩將安全座椅作隨機分 配單數日與偶數日分別放 L 及 R 之位置連續觀察 3 個月比較其哭鬧 L 及 R 頻 率，發現 L 哭鬧頻率較 R 多，假設哭鬧頻率達統計檢定力，某人提出下列論 點： a.L 較 R 哭鬧頻率高，可能是因為在L 位置之小孩年齡較小，較易哭鬧。 b.L 較 R 哭鬧頻率高，可能是因為母親駕駛技術差異。 c.L 較 R 哭鬧頻率高，可能是因為車子種類不同。 d.L 較 R 哭鬧頻率高 ， 可能是因為小孩在L 位置較不易看到母親而容易哭鬧。 上述敍述何者不正確？",
