    "question": "現代學童近視狀況日趨嚴重，有些家長質疑這是玩電玩和看電視所造成的，台 南縣衛生局因此委託流行病學專家對國小學童進行調查 ， 該學者因此以問卷方式 量化學童每週花在電玩及電視上的時間 ， 並和近視度數之間進行關聯分析 ， 他使 用的是相關係數（ Regression Coefficient）及線性迴歸分析方法，請問下列 敘述何者為誤？",
