    "question": "吾人欲比較北部區域不同型態的檢查對象違法家次的比例，他想出下列數種分析 方法（假設各家次間的檢查互為獨立的情況下） ○1 比較○C 欄，由於比較組數≧3，因此使用ANOVA Test ○2 利用【○A 欄－○B 欄】得到不同檢查對象之合格家次，再輔以○B 欄的資料執行卡 方檢定（X Test） ○3 因北部區域中醫醫院診所僅觀察到5 家違法家次，因此不符合大樣本假說，不 能用 X Test，而需改用Fisher Exact Test ○4 可利用羅吉斯迴歸分析（Logistic Regression） 請問以上敘述何者不正確？",
