    "id": "tainan-98-0118-16",
    "question": "Bosschev 及 Smit(1998)提出12 個項目來測量自我效能 如果事情複雜我不會不想嘗試。 如果工作第一次沒做好，我會持續進行嘗試。 我似乎不能夠處理大部份日常生活問題。 我一定努力依照計畫完成預定工作。 失敗讓我再嘗試困難度增高。 我儘量避免嘗試新的困難。 當面臨新的困難事務但開始不感興趣時，我會很快放棄。 即使執行目標遇到不愉快，我也會竭盡完成。 當我決定做此事會勇往直前。 遇到不可預期之困難通常不會處理得很好。 ○11 我對於做事之能力感到沒有安全感。 ○12 當我設定重要目標時，我很少達成它。 下表為12 項目標準化因素負荷之結果 項目 因子1 因子 2 因子 3 因子 4 因子 5  0.74 0.01 0.28 0.25 0.16  0.10 0.53 0.08 0.08 0.03  0.05 0.04 0.61 0.17 0.08  0.07 0.60 0.02 0.25 0.07  0.08 0.51 0.09 0.06 0.09  0.58 0.08 0.12 0.13 0.12  0.61 0.13 0.07 0.10 0.14  0.11 0.56 0.05 0.28 0.18  0.20 0.57 0.04 0.05 0.05  0.21 0.14 0.63 0.03 0.07 ○11 0.17 0.07 0.61 0.09 0.08 ○12 0.15 0.05 0.51 0.06 0.11 根據上述因素分析之結果，您建議採取幾個因子模式",
