    "question": "依上表 1 及上表 2 資料，若 FOBT≧100 以上者視為陽性個案，若大腸鏡檢順從率為 100%，以下何者正確？ 編號 1 為偽陽性個案。 編號 3 為篩檢偵測個案。 編號 4 為拒絕個案。 編號 9 為偽陰性個案。",
