    "question": "若此樣本中（n=800），現有 X 人糖化血素值高於 10（％），則糖化血素高於10（％） 的比例之最佳估計值為 pˆ = nx ，若欲檢定該比例是否比台南縣糖尿病照護網中的病人 高 （其比例為p0） ， 吾人提議可依檢定統計量 （Z） 是否落入拒絕域 （Rejection Area）， 或依信賴區間（Confidence Interval）是否涵蓋P0 進行推論，請問以下何者正確(其 中 qˆ =1- pˆ ，q0=1-p0)?",
