    "question": "假設構成代謝症候群有五個因子分別為 X1，X2，X3，X4，X5 並定義各變項為二分變項(Binary variable) 也就是 X1－X5 之值分別是異常=1，正常=0，某地區利用實證資料及相關廻歸模式得到這五個變項與 心臟血管疾病之關係 求得 綜合危險分數 (Composite Risk Score ；CRS) 如下： CRS=c( 常 數)+a1X1+a2X2+a3X3+a4X4+a5X5，a1=50，a2=30，a3=10，a4=20，a5=40，c=10 上述 CRS 分數可能有幾種？",
