    "question": "某護理長為了找出最有效的邀請方式以提高轄區內 「行動醫院、全民健檢」的受檢人數，於是她 讓衛生所內 4 名地段護士分別採用明信片、地段護士電訪、地段護士家訪、鄰里長家訪等四種不 同的邀請方式邀請民眾參加「行動醫院、全民健檢」活動，並得到以下結果： 邀請方式 邀請人數 受檢人數 地段 A 明信片 500 25 地段 B 護士電訪 250 25 地段 C 護士家訪 200 30 地段 D 鄰里長家訪 100 30 該護理長同時收集了成本資料，明信片每張 2.5 元，處理郵寄資料(如黏貼地址等)每人每小時可 處理 100 張明信片，電訪每人每小時平均可成功聯繫5 名民眾，電話費用每通平均約10 元，家訪 每小時平均可成功拜訪 1 名民眾，鄰里長家訪每小時平均可成功拜訪 5 名民眾。假設公衛護士與 鄰里長時薪約200 元，請問下列何者正確？ ○1 明信片與電訪的邀請效果相同 ○2 以地段護士家訪的邀請效果最好 ○3 地段護士家訪的受檢率是電訪的1.5 倍 ○4 地段護士家訪的受檢率是鄰里長家訪的 1.5 倍",
