    "id": "tainan-98-0801-24",
    "question": "牙周病為社區常見的口腔疾病，為了解一般社區民眾的牙周病盛行率，某牙醫師結合社區整合式 篩檢對受檢民眾進行牙周檢查。社區牙周病指標(CPI)為常見的牙周病指標之一，其值為0～4 的 整數，分別代表健康、牙齦流血、牙結石、4～5mm 的牙周囊袋，及6mm 或更深的牙周囊袋。若進 行多變項分析(以具有 6mm 或更深的牙周囊袋為個案定義)，得到下列結果： OR(95%CI) 年齡 35—39 歲 1.00 40—44 歲 1.39(1.18—1.64) 性別 女 1.00 男 1.63(1.34—1.99) 教育程度 國中以下 2.23(1.78—2.81) 高中 1.49(1.22—1.81) 大專院校 1.00 請問下列敍述何者正確？ 僅有性別與牙周病具有顯著的相關。 教育程度愈低者愈容易出現嚴重牙周病。 此結果有助於找出牙周病的高危險群。",
    "options": {
      "A": "",
      "B": "",
      "C": "",
      "D": " 題組六(25-26)： 成人牙周病的罹患率很高，早期檢查以及積極治療極為重要。某研究為了評估牙周病早期檢查和介入 治療的效益，因此進行相關研究，其研究流程圖如下： 該研究在收案時即先對個案根據牙周指數(Community Periodontal Index,CPI)進行評估，經過一個 月的完整治療後，再進行一次評估，並於 18 個月後再進行評估。 【註：CPI 指數由 0 至 4，表示牙周 狀況最健康至最嚴重之不同程度】"
    },
