    "question": "公益彩券刮刮樂今年中秋節欲推出中秋加碼活動，該彩券有兩個關卡，第一關幸運骰子刮刮樂， 如刮中 ，可以選擇拿回 1000 元，但無法晉級第二關。但若放棄此彩金，可和第一關刮中其他 點數的人一樣再闖第二關，只要第二關刮中金元寶，即可拿回金元寶旁的彩金金額。若每張彩券 定價 300 元，第一關骰子刮刮樂為公正的骰子，而第一關刮中 會放棄彩金的比例為 20％，第二 關刮中金元寶的機率及對應彩金如下表 刮中金元寶機率 可得彩金 100,000 2,000 3,000 4,000 5,000 6,000 請問每張彩券預期利潤為何？",
