    "id": "tainan-99-0425-06",
    "question": "( ) 假設高血壓存活時間之分佈是指數分佈，存活機率函數為e -λt (e 是自然 對數，t 是追蹤時間，λ是平均死亡風險率(hazard rate)，也就是平均 存活時間之倒數 ) ，下列敘述何者 正確 ? (e -0.4 =0.67 ；e -0.6 =0.55 ； e -0.8 =0.45；e -1.0 =0.37；e -1.2 =0.30；e -1.6 =0.20；e -1.8 =0.17；e -2 =0.14) ○1 10 年內 A 地區高血壓病人死亡之機率為86% ○2 兩地區正常人在10 年內高血壓病人存活機率相同",
