    "question": "( ) 某衛生所欲進行家訪及電訪兩種組合訪查方式，若此家訪方式針對 30%、50%及 70%人口可分別增加12%、15%及 18%行動醫院全民健檢參與 率，而電訪 30%、50%及 70%人口，可分別增加 2%、6%及 10%行動醫院 全民健檢參與率 。 若同時進行家訪70%及電訪70%人口為不可能實行之 策略，其他組合策略若依賽局理論欲選擇參與率最大化策略應為",
