    "question": "( ) 台南縣衛生局欲評估飲食及運動介入對於血糖偏高民眾是否具有降血 糖作用，因此對近三個月於台南縣「行動醫院，全民健檢」活動中， 其空腹血糖100-125 mg /dL 無糖尿病史且BMI≧30 之200 位其年齡40-69 民眾，進行隨機分派（Randomized Controlled Trial ）介入研究， 執行六個月後，發現有飲食及運動介入組比控制組（無任何介入）之 空腹血糖有顯著下降。請問該研究之空腹血糖前後測表示應趨於下列 哪一圖？（ —介入組， --- 控制組 ）",
